const output = document.querySelector('#qty');
const up = document.querySelector('.qty__up');

let quantity = 1;

const render = () => {
  output.textContent = `${quantity}개`;
};

up.addEventListener('click', () => {
  quantity = quantity + 1;
  render();
});

const output = document.querySelector('#qty');
const up = document.querySelector('.qty__up');
const down = document.querySelector('.qty__down');

let quantity = 1;

const render = () => {
  output.textContent = `${quantity}개`;
};

up.addEventListener('click', () => {
  quantity = quantity + 1;
  render();
});

down.addEventListener('click', () => {
  if (quantity > 1) {
    quantity = quantity - 1;
    render();
  }
});
